-- A9 - COMPLETE LOAD
-- Production Order / MRP (consumes RM/EC/MC/SA, produces FG)
-- ============================================================================

-- FASE 1: DROP (cascade) - tabelas novas, esperado erro 'table not found' na 1a execucao, usar Skip All
DROP TABLE INDUSTRIAL_DATA.PRODUCTION_ORDER_COMPONENT CASCADE;
DROP TABLE INDUSTRIAL_DATA.PRODUCTION_ORDER CASCADE;
DROP TABLE INDUSTRIAL_DATA.PRODUCTION_ORDER_STATUS CASCADE;

-- FASE 2: CREATE CONFIG TABLE
CREATE TABLE INDUSTRIAL_DATA.PRODUCTION_ORDER_STATUS (STATUS_CODE NVARCHAR(10) NOT NULL PRIMARY KEY, STATUS_TEXT NVARCHAR(60) NOT NULL);

-- FASE 3: LOAD CONFIG DATA

-- FASE 4: CREATE PRODUCTION ORDER HEADER + COMPONENT
CREATE TABLE INDUSTRIAL_DATA.PRODUCTION_ORDER (
  AUFNR NVARCHAR(10) NOT NULL PRIMARY KEY,
  MATNR NVARCHAR(10) NOT NULL,
  WERKS NVARCHAR(4) NOT NULL,
  STATUS_CODE NVARCHAR(10) NOT NULL,
  QUANTITY_PLANNED DECIMAL(15, 2) NOT NULL,
  QUANTITY_CONFIRMED DECIMAL(15, 2) NOT NULL,
  START_DATE DATE NOT NULL,
  FINISH_DATE DATE,
  FOREIGN KEY (MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  FOREIGN KEY (WERKS) REFERENCES INDUSTRIAL_DATA.PLANT(WERKS),
  FOREIGN KEY (STATUS_CODE) REFERENCES INDUSTRIAL_DATA.PRODUCTION_ORDER_STATUS(STATUS_CODE),
  CHECK (QUANTITY_PLANNED > 0),
  CHECK (QUANTITY_CONFIRMED >= 0)
);

CREATE TABLE INDUSTRIAL_DATA.PRODUCTION_ORDER_COMPONENT (
  COMPONENT_ID INT NOT NULL PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
  AUFNR NVARCHAR(10) NOT NULL,
  COMPONENT_NO INT NOT NULL,
  COMPONENT_MATNR NVARCHAR(10) NOT NULL,
  QUANTITY_REQUIRED DECIMAL(15, 2) NOT NULL,
  QUANTITY_CONSUMED DECIMAL(15, 2) NOT NULL,
  FOREIGN KEY (AUFNR) REFERENCES INDUSTRIAL_DATA.PRODUCTION_ORDER(AUFNR),
  FOREIGN KEY (COMPONENT_MATNR) REFERENCES INDUSTRIAL_DATA.MATERIAL(MATNR),
  CHECK (QUANTITY_REQUIRED > 0),
  CHECK (QUANTITY_CONSUMED >= 0)
);

